"""Wallet resource for retrieving wallet balance, auto-reload, and rates."""

from __future__ import annotations

from tinyfish._utils.resource import BaseAsyncAPIResource, BaseSyncAPIResource

from .types import WalletResponse


class WalletResource(BaseSyncAPIResource):
    """Retrieve the caller's wallet (sync)."""

    def get(self) -> WalletResponse:
        """Get the caller's wallet: balance, auto-reload state, per-contract rates,
        and any in-flight top-up.

        Returns:
            WalletResponse with the full wallet shape.

        Raises:
            AuthenticationError: Invalid API key.
        """
        return self._get("/v1/wallet", cast_to=WalletResponse)


class AsyncWalletResource(BaseAsyncAPIResource):
    """Retrieve the caller's wallet (async)."""

    async def get(self) -> WalletResponse:
        """Get the caller's wallet: balance, auto-reload state, per-contract rates,
        and any in-flight top-up.

        Async version of `WalletResource.get()`.

        Returns:
            WalletResponse with the full wallet shape.

        Raises:
            AuthenticationError: Invalid API key.
        """
        return await self._get("/v1/wallet", cast_to=WalletResponse)
